package com.brazilsoccer.mcp;

import java.time.*;import java.util.*;import java.util.stream.*;

/** Query and aggregate operations used by both MCP tools and application callers. */
public final class SoccerService {
  private final SoccerRepository data; public SoccerService(SoccerRepository data){this.data=data;}
  public List<Match> findMatches(String team,String opponent,String competition,String season,LocalDate from,LocalDate to,int limit){return data.matches().stream().filter(m->team==null||team.isBlank()||m.involves(team)).filter(m->opponent==null||opponent.isBlank()||m.involves(opponent)).filter(m->competition==null||competition.isBlank()||TeamNames.normalize(m.competition()).contains(TeamNames.normalize(competition))).filter(m->season==null||season.isBlank()||m.season().equals(season)).filter(m->from==null||m.date()==null||!m.date().isBefore(from)).filter(m->to==null||m.date()==null||!m.date().isAfter(to)).sorted(Comparator.comparing(Match::date,Comparator.nullsLast(Comparator.reverseOrder()))).limit(Math.max(1,Math.min(limit,500))).toList();}
  public TeamStats teamStats(String team,String season,String competition,boolean homeOnly){List<Match> ms=findMatches(team,null,competition,season,null,null,10000).stream().filter(m->!homeOnly||TeamNames.matches(m.home(),team)).toList();int w=0,d=0,l=0,gf=0,ga=0;for(Match m:ms){if(m.homeGoals()==null||m.awayGoals()==null)continue;boolean home=TeamNames.matches(m.home(),team);int f=home?m.homeGoals():m.awayGoals(),a=home?m.awayGoals():m.homeGoals();gf+=f;ga+=a;if(f>a)w++;else if(f==a)d++;else l++;}return new TeamStats(team,ms.size(),w,d,l,gf,ga);}
  public HeadToHead headToHead(String first,String second,String season,String competition){List<Match> ms=findMatches(first,second,competition,season,null,null,10000);int a=0,b=0,d=0;for(Match m:ms){if(m.homeGoals()==null||m.awayGoals()==null)continue;boolean firstHome=TeamNames.matches(m.home(),first);int x=firstHome?m.homeGoals():m.awayGoals(),y=firstHome?m.awayGoals():m.homeGoals();if(x>y)a++;else if(x<y)b++;else d++;}return new HeadToHead(first,second,ms.size(),a,b,d);}
  public List<Standing> standings(String season,String competition){Map<String,int[]> t=new HashMap<>();for(Match m:findMatches(null,null,competition,season,null,null,100000)){if(m.homeGoals()==null||m.awayGoals()==null)continue;play(t,m.home(),m.homeGoals(),m.awayGoals());play(t,m.away(),m.awayGoals(),m.homeGoals());}return t.entrySet().stream().map(e->new Standing(e.getKey(),e.getValue()[0],e.getValue()[1],e.getValue()[2],e.getValue()[3],e.getValue()[4],e.getValue()[5])).sorted(Comparator.comparingInt(Standing::points).reversed().thenComparing(Comparator.comparingInt(Standing::goalDifference).reversed()).thenComparing(Comparator.comparingInt(Standing::goalsFor).reversed()).thenComparing(Standing::team)).toList();}
  private static void play(Map<String,int[]> t,String name,int f,int a){int[] x=t.computeIfAbsent(TeamNames.normalize(name),k->new int[]{0,0,0,0,0,0});x[0]++;x[4]+=f;x[5]+=a;if(f>a)x[1]++;else if(f==a)x[2]++;else x[3]++;}
  public List<Player> findPlayers(String name,String nationality,String club,String position,int limit){return data.players().stream().filter(p->contains(p.name(),name)).filter(p->contains(p.nationality(),nationality)).filter(p->contains(p.club(),club)).filter(p->contains(p.position(),position)).sorted(Comparator.comparing(Player::overall,Comparator.nullsLast(Comparator.reverseOrder()))).limit(Math.max(1,Math.min(limit,500))).toList();}
  private static boolean contains(String value,String query){return query==null||query.isBlank()||TeamNames.normalize(value).contains(TeamNames.normalize(query));}
  public List<Match> biggestWins(String competition,int limit){return data.matches().stream().filter(m->competition==null||competition.isBlank()||TeamNames.normalize(m.competition()).contains(TeamNames.normalize(competition))).filter(m->m.homeGoals()!=null&&m.awayGoals()!=null).sorted(Comparator.comparingInt(Match::goalDifference).reversed().thenComparing(Match::date,Comparator.nullsLast(Comparator.reverseOrder()))).limit(Math.max(1,Math.min(limit,100))).toList();}
  public record TeamStats(String team,int matches,int wins,int draws,int losses,int goalsFor,int goalsAgainst){public double winRate(){return matches==0?0:100.0*wins/matches;}}
  public record HeadToHead(String first,String second,int matches,int firstWins,int secondWins,int draws){}
  public record Standing(String team,int played,int wins,int draws,int losses,int goalsFor,int goalsAgainst){public int points(){return wins*3+draws;}public int goalDifference(){return goalsFor-goalsAgainst;}}
}
